// ===== GAME HELPERS =====
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

static TOKEN_COUNTER: AtomicU64 = AtomicU64::new(0);

fn random_bytes(n: usize) -> Vec<u8> {
    // Try /dev/urandom, fallback to time+counter hash
    if let Ok(mut f) = std::fs::File::open("/dev/urandom") {
        use std::io::Read;
        let mut buf = vec![0u8; n];
        if f.read_exact(&mut buf).is_ok() {
            return buf;
        }
    }
    // fallback: simple xorshift seeded with time+pid+counter
    let now = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_nanos() as u64).unwrap_or(123456789);
    let cnt = TOKEN_COUNTER.fetch_add(1, Ordering::Relaxed);
    let pid = std::process::id() as u64;
    let mut seed = now.wrapping_add(cnt.wrapping_mul(0x9e3779b97f4a7c15)).wrapping_add(pid.wrapping_mul(0xbf58476d1ce4e5b9));
    if seed == 0 { seed = 0x853c49e6748fea9b; }
    let mut out = Vec::with_capacity(n);
    for _ in 0..n {
        // xorshift64*
        seed ^= seed >> 12;
        seed ^= seed << 25;
        seed ^= seed >> 27;
        let v = seed.wrapping_mul(0x2545F4914F6CDD1D);
        out.push((v >> 56) as u8);
    }
    out
}

fn generate_player_token() -> String {
    let b = random_bytes(16);
    let mut s = String::with_capacity(32);
    for byte in b {
        s.push_str(&format!("{:02x}", byte));
    }
    s
}

fn generate_game_code(conn: &Connection) -> String {
    const CHARSET: &[u8] = b"ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
    for _ in 0..100 {
        let b = random_bytes(5);
        let mut code = String::with_capacity(5);
        for byte in b {
            let idx = (*byte as usize) % CHARSET.len();
            code.push(CHARSET[idx] as char);
        }
        // check uniqueness
        let exists: i64 = conn.query_row("SELECT COUNT(*) FROM games WHERE code=?1", params![code], |r| r.get(0)).unwrap_or(1);
        if exists == 0 {
            return code;
        }
    }
    // fallback with time
    let now = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0);
    format!("G{:04}", now % 10000)
}

fn qr_svg_for(data: &str) -> String {
    match qrcode::QrCode::new(data.as_bytes()) {
        Ok(code) => {
            let svg = code.render::<qrcode::render::svg::Color>().min_dimensions(200, 200).build();
            // strip xml prolog for inline embedding
            if let Some(pos) = svg.find("<svg") {
                svg[pos..].to_string()
            } else {
                svg
            }
        }
        Err(_) => String::from("<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 100 100\"><rect width=\"100\" height=\"100\" fill=\"white\"/><text x=\"50\" y=\"50\" text-anchor=\"middle\">QR</text></svg>"),
    }
}

fn host_from_headers(headers: &HeaderMap) -> String {
    if let Some(v) = headers.get(header::HOST) {
        if let Ok(s) = v.to_str() {
            let s = s.trim();
            if !s.is_empty() {
                return s.to_string();
            }
        }
    }
    // fallback: try X-Forwarded-Host
    if let Some(v) = headers.get("x-forwarded-host") {
        if let Ok(s) = v.to_str() {
            let s = s.trim();
            if !s.is_empty() {
                return s.to_string();
            }
        }
    }
    let port = env::var("PORT").unwrap_or_else(|_| "3000".to_string());
    format!("localhost:{}", port)
}

fn parse_cookies(headers: &HeaderMap) -> HashMap<String, String> {
    let mut map = HashMap::new();
    for val in headers.get_all(header::COOKIE) {
        if let Ok(s) = val.to_str() {
            for part in s.split(';') {
                let part = part.trim();
                if part.is_empty() { continue; }
                if let Some((k, v)) = part.split_once('=') {
                    map.insert(k.trim().to_string(), v.trim().to_string());
                }
            }
        }
    }
    map
}

fn wants_json(headers: &HeaderMap) -> bool {
    if let Some(v) = headers.get("x-requested-with") {
        if let Ok(s) = v.to_str() {
            if s.to_lowercase().contains("xmlhttprequest") || s.to_lowercase().contains("fetch") {
                return true;
            }
        }
    }
    if let Some(v) = headers.get(header::ACCEPT) {
        if let Ok(s) = v.to_str() {
            if s.contains("application/json") {
                return true;
            }
        }
    }
    // fetch() default sends */*, but our JS will send Accept: application/json explicitly
    false
}

