}

fn count_answers_for(conn: &Connection, game_id: i64, question_id: i64) -> i64 {
    conn.query_row("SELECT COUNT(*) FROM answers WHERE game_id=?1 AND question_id=?2", params![game_id, question_id], |r| r.get(0)).unwrap_or(0)
}

fn counts_per_option(conn: &Connection, game_id: i64, question_id: i64) -> HashMap<i64, i64> {
    let mut map = HashMap::new();
    let mut stmt = match conn.prepare("SELECT option_id, COUNT(*) FROM answers WHERE game_id=?1 AND question_id=?2 GROUP BY option_id") {
        Ok(s) => s,
        Err(_) => return map,
    };
    let rows = stmt.query_map(params![game_id, question_id], |row| {
        let oid: i64 = row.get(0)?;
        let c: i64 = row.get(1)?;
        Ok((oid, c))
    });
    if let Ok(rows) = rows {
        for r in rows.flatten() {
            map.insert(r.0, r.1);
        }
    }
    map
}

fn get_player_by_token(conn: &Connection, game_id: i64, token: &str) -> Option<Player> {
    let t = token.trim();
    if t.is_empty() { return None; }
    conn.query_row("SELECT id, game_id, name, token FROM players WHERE game_id=?1 AND token=?2", params![game_id, t], |row| {
        Ok(Player { id: row.get(0)?, game_id: row.get(1)?, name: row.get(2)?, token: row.get(3)? })
    }).optional().unwrap()
}

fn find_player_for_game(conn: &Connection, game: &Game, headers: &HeaderMap, query_token: Option<&str>) -> Option<Player> {
    // 1. query token
    if let Some(qt) = query_token {
        if !qt.trim().is_empty() {
            if let Some(p) = get_player_by_token(conn, game.id, qt) {
                return Some(p);
            }
        }
    }
    // 2. X-Player-Token header
    if let Some(v) = headers.get("x-player-token") {
        if let Ok(s) = v.to_str() {
            if !s.trim().is_empty() {
                if let Some(p) = get_player_by_token(conn, game.id, s) {
                    return Some(p);
                }
            }
        }
    }
    // 3. cookies: try specific then all values
    let cookies = parse_cookies(headers);
    // specific names
    let code = &game.code;
    for key in [format!("quizzy_{}", code), format!("qz_{}", code), "quizzy_player".to_string(), "player_token".to_string(), "player".to_string()] {
        if let Some(v) = cookies.get(&key) {
            if let Some(p) = get_player_by_token(conn, game.id, v) {
                return Some(p);
            }
        }
    }
    // try all cookie values as tokens (handles any name)
    for v in cookies.values() {
        // avoid huge values
        if v.len() > 200 { continue; }
        // URL-decode? cookies may be encoded; try raw and decoded
        let decoded = percent_decode(v);
        for cand in [v.as_str(), decoded.as_str()] {
            if let Some(p) = get_player_by_token(conn, game.id, cand) {
                return Some(p);
            }
        }
    }
    None
}

fn get_player_answer(conn: &Connection, player_id: i64, question_id: i64) -> Option<i64> {
    conn.query_row("SELECT option_id FROM answers WHERE player_id=?1 AND question_id=?2", params![player_id, question_id], |r| r.get(0)).optional().unwrap()
}

