                }
                let mark = if picked {
                    r##"<span class="play-option__mark">Your answer</span>"##
                } else {
                    ""
                };
                opts_html.push_str(&format!(
                    r##"<div class="{cls}"><span class="play-option__letter">{l}</span><span class="play-option__title">{body}</span>{mark}</div>"##,
                    cls = cls,
                    l = html_escape(&l),
                    body = html_escape(&o.body),
                    mark = mark,
                ));
            }
            let (res_text, res_cls) = match st.result.as_deref() {
                Some("correct") => ("Correct!", "play-status--right"),
                Some("wrong") => ("Wrong!", "play-status--wrong"),
                _ => ("No answer", "play-status--neutral"),
            };
            return format!(
                r##"<div class="play-question__num" id="q-progress">Question {num} of {total}</div><div class="play-question__body" id="q-body">{qbody}</div><div class="play-options is-locked" id="play-options">{opts}</div><div class="play-status {cls}" id="play-result">{res}</div>"##,
                num = num,
                total = total,
                qbody = html_escape(&q.body),
                opts = opts_html,
                cls = res_cls,
                res = res_text,
            );
        }
        return format!(
            r##"<div class="waiting"><div class="waiting__gem">?</div><h1 id="hi-name">Hi, {name}!</h1><div class="play-lead">Waiting for the quiz to start…</div></div>"##,
            name = html_escape(&name),
        );
    }
    // unknown status fallback
    r##"<div class="waiting"><div class="waiting__gem">?</div><h1>Waiting…</h1></div>"##.to_string()
}

